 {q:'How are you?',qA:'a_t_how_are_you.mp3',qSlow:'a_t_how_are_you_slow.mp3',ans:"I'm fine, thank you.",ansA:'a_t_im_fine.mp3',frame:"I'm ___, thank you."}
