function gradeButtons(st){return `<button class="grade" data-g="A" data-st="${st}">A · Independent</button><button class="grade" data-g="B" data-st="${st}">B · With help</button><button class="grade" data-g="C" data-st="${st}">C · Not yet</button>`}
function noAr(){document.body.classList.remove('ar-on');$('#btn-ar').setAttribute('aria-pressed','false')}
function ltrBtn(L){return `<button class="word-opt" data-w="${L}" style="color:${TILE[L]}">${L}</button>`}
