function sceneHTML(id){
 if(id==='enter')return `<div class="scene"><div class="sun"></div><div class="door" style="right:46px"></div><img class="sc-char" style="left:66px" src="${A}sec_labeeb_clean.png" alt="boy walks into class"><div class="arr" style="right:120px">${ARROW}</div></div>`;
 if(id==='meet')return `<div class="scene"><img class="sc-char" style="left:44px;height:190px" src="${A}sec_char_noura.png" alt="Noura"><img class="sc-char" style="right:44px;transform:scaleX(-1)" src="${A}sec_labeeb_clean.png" alt="Labeeb"></div>`;
 return `<div class="scene"><div class="door" style="left:46px"></div><img class="sc-char" style="left:170px" src="${A}sec_labeeb_clean.png" alt="boy leaves"><div class="arr" style="right:26px">${ARROW}</div><div class="wave"></div></div>`;
}
function icSVG(k){const m={chat:'<svg width="66" height="66" viewBox="0 0 24 24" fill="none" stroke="#1670e8" stroke-width="2"><path d="M21 12a8 8 0 0 1-8 8H4l2-3a8 8 0 1 1 15-5z"/><path d="M8.5 12h.01M12 12h.01M15.5 12h.01" stroke-linecap="round" stroke-width="3"/></svg>',door:'<svg width="66" height="66" viewBox="0 0 24 24" fill="none" stroke="#37b56a" stroke-width="2"><rect x="5" y="3" width="14" height="18" rx="2"/><circle cx="15" cy="12" r="1.4" fill="#37b56a"/><path d="M9 12h6" stroke-linecap="round"/></svg>',palette:'<svg width="66" height="66" viewBox="0 0 24 24" fill="none" stroke="#ff735e" stroke-width="2"><path d="M12 3a9 9 0 1 0 0 18c1.5 0 2-1 1.4-2.2-.7-1.3.1-2.3 1.6-2.3H17a4 4 0 0 0 4-4c0-5.2-4-9.5-9-9.5z"/><circle cx="7.5" cy="11.5" r="1.3" fill="#2f80ed" stroke="none"/><circle cx="12" cy="7.5" r="1.3" fill="#37b56a" stroke="none"/><circle cx="16.5" cy="11.5" r="1.3" fill="#ffd93b" stroke="none"/></svg>',abc:'<svg width="66" height="66" viewBox="0 0 24 24" fill="none" stroke="#8e5bd6" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="4"/><path d="M8 16l2.2-7h.6L13 16M8.9 13h3.2M15.5 10v6" stroke-linecap="round" stroke-linejoin="round"/></svg>'};return m[k]}

