addScreen('أهلاً · Get ready',`<div style="width:940px;text-align:center"><h1 class="title">School Practice<span style="color:var(--coral)"> · </span><span style="color:var(--blue)">تدريب المدرسة</span></h1><p class="subtitle" style="font-size:24px">الصوت واضح، والكتاب والقلم والورقة بالقرب منك</p><div class="grid" style="grid-template-columns:repeat(3,1fr);margin-top:34px"><div class="card goal-card"><span class="letter">01</span><strong>الصوت</strong><p>شغّل الميكروفون</p></div><div class="card goal-card"><span class="letter">02</span><strong>الكتاب</strong><p>Workbook صفحة 63–70</p></div><div class="card goal-card"><span class="letter">03</span><strong>القلم والورقة</strong><p>جاهزان للتدريب</p></div></div><div class="row" style="margin-top:30px"><button class="mini-pill blue" data-audio="a_t_soundcheck.mp3">اختبار الصوت</button></div></div>`,null);

/* S2 · Lead-in：首字母 + 两色提取（滚动复习，90 秒） */
addScreen('Warm up · letter & colors',`<div class="layout"><div class="card copy"><span class="source-badge">WARM UP</span><h2 style="font-size:32px;margin-top:12px">What color is it? <button class="speaker small" data-audio="a_t_what_color.mp3" style="vertical-align:middle"></button></h2><div class="row" id="w-colors" style="margin-top:18px"></div></div><div class="card copy" style="text-align:center"><h2 style="font-size:32px;margin-top:0">Say the letter <button class="speaker small" data-audio="a_t_listen_letters.mp3" style="vertical-align:middle"></button></h2><div id="w-ltr" style="margin-top:14px"></div></div></div><div class="teacher"><b>滚动复习（限 90 秒）</b>：随机 2 色 + 随机 1 个 A–H 字母，学生看卡说名称；两项以上独立即过，有困难只慢音一次，不长补——本课重点在四站任务。</div>`,el=>{return{onEnter(){const picks=shuffle(COLORS).slice(0,2);el.querySelector('#w-colors').innerHTML=picks.map(c=>`<button class="swatch-chip" style="background:${c.hex}" data-audio="a_t_${c.en}.mp3"></button>`).join('');const L=shuffle(KEY8)[0];el.querySelector('#w-ltr').innerHTML=`<button class="ltr-card" data-audio="a_t_ltr_${L}.mp3" style="margin:auto"><div class="big" style="color:${TILE[L]}">${L}</div><div class="nm">say the letter name</div></button>`}}});

/* S3 · 四站任务地图 + 过关规则（权威承诺页） */
addScreen('Today · four stations',`<div class="mission"><div class="row" style="gap:18px"><span class="source-badge">SCHOOL PRACTICE · WORKBOOK pp.63–70</span><img src="${A}textbook_cover.png" alt="We Can 1 textbook" style="height:120px;border-radius:12px;box-shadow:var(--shadow)"></div><h1 class="title sm" style="margin-top:14px">Four stations.<br><span class="accent">Pass three on your own.</span> <button class="speaker small" data-audio="a_t_four_stations.mp3" style="vertical-align:middle"></button></h1><div class="station-map">${['qa','sit','col','ltr'].map((k,i)=>`<div class="station-card" style="border-top-color:${['#1670e8','#37b56a','#ff735e','#8e5bd6'][i]}"><div class="ic">${icSVG(ST_META[k].icon)}</div><strong>Station ${i+1}</strong><p>${ST_META[k].name}</p></div>`).join('')}</div><p class="ar subtitle">أربع محطات اليوم — تنجح في ثلاث منها بنفسك</p></div><div class="teacher"><b>承诺页</b>：带学生指读四站图标，说清规则——每站先听再做，<b>3/4 独立通过即达标</b>；教材徽章页码指向 Workbook pp.63–70。不展开讲题，30 秒内翻页。</div>`,null);

