addScreen('School words · listen circle match trace',`<div style="text-align:center"><h1 class="title sm">Four school words</h1><p class="subtitle" style="margin-top:6px">Hear it · do the action</p><div class="instr-grid">${[['Listen','a_t_listen.mp3','tile_listen.png','اسمع'],['Circle','a_t_circle.mp3','tile_circle.png','ضع دائرة'],['Match','a_t_match.mp3','tile_match.png','صِل'],['Trace','a_t_trace.mp3','tile_trace.png','تتبّع']].map(([w,au,img,ar])=>`<button class="instr-card" data-audio="${au}"><img src="${A}${img}" alt="${w}"><strong>${w}</strong><p class="ar" style="color:var(--muted);font-size:16px;margin-top:4px">${ar}</p></button>`).join('')}</div></div><div class="teacher"><b>操作词只教"做动作"</b>：听词 → 学生用动作演示（指耳/空中画圈/两手相连/空描）。4 中 3 正确即过。<b>阿语只翻译操作词，绝不翻译后面的答案。</b>书写类 trace 卡住转家庭作业，不占课堂时间。</div>`,null);

/* S5 · Station 1 · 姓名/状态听问答（先说后选） */
addScreen('Station 1 · listen and answer',`<div style="text-align:center;width:1000px"><div class="row" style="justify-content:center;gap:16px"><span class="source-badge">STATION 1</span><h1 class="title sm">Listen. Say it. Then tap.</h1></div><div class="card copy" style="margin-top:18px"><div class="row"><button class="speaker large" id="q-play"></button><div style="text-align:left"><p style="font-size:20px;color:var(--muted);font-weight:800">1 · Listen to the question</p><p style="font-size:20px;color:var(--muted);font-weight:800">2 · Say YOUR answer out loud</p><p style="font-size:20px;color:var(--navy);font-weight:900">3 · Tap the same answer</p></div></div><div id="q-choices" class="stack" style="margin-top:18px;display:none"></div><div class="row" style="margin-top:16px"><button class="mini-pill blue" id="q-show">Show choices</button></div><div class="dots" id="q-dots">${'<span class="dot"></span>'.repeat(2)}</div></div></div><div class="teacher"><b>先说后选是硬流程</b>：播问题 → 学生<b>口头</b>说出自己的答案 → 再点 Show choices 让其指认相同意思的选项。防止"会点不会说"。学生口头卡住：给首词（My… / I'm…）一次，仍说不出记入 Check 1。<div class="teacher-row"><button class="error" id="q-slow">▶ Slow question</button><button class="error" id="q-again">▶ Replay</button></div></div>`,el=>{let r=0;const dots=[...el.querySelectorAll('#q-dots .dot')];function round(){const item=QA[r];el.querySelector('#q-choices').style.display='none';el.querySelector('#q-choices').innerHTML='';el.querySelector('#q-show').style.display='';el.querySelector('#q-play').onclick=()=>play(item.qA);el.querySelector('#q-slow').onclick=()=>play(item.qSlow);el.querySelector('#q-again').onclick=()=>play(item.qA);el.querySelector('#q-show').onclick=()=>{el.querySelector('#q-show').style.display='none';const other=QA[1-r].ans;el.querySelector('#q-choices').innerHTML=shuffle([item.ans,other]).map(t=>`<button class="phrase-opt" data-w="${t}">${t}</button>`).join('');el.querySelector('#q-choices').style.display='grid';el.querySelectorAll('#q-choices [data-w]').forEach(b=>b.onclick=()=>{if(b.dataset.w===item.ans){b.classList.add('good');sfx('sfx_correct.mp3');play(item.ansA);dots[r]?.classList.add('done');r++;if(r<2)setTimeout(round,1200);else setTimeout(()=>{el.querySelector('#q-choices').innerHTML='<p style="font-size:26px;font-weight:900;color:var(--green)">Station 1 clear!</p>';sfx('sfx_success.mp3')},1200)}else{b.classList.add('bad');sfx('sfx_wrong.mp3');setTimeout(()=>b.classList.remove('bad'),350)}})}}return{onEnter(){r=0;dots.forEach(d=>d.classList.remove('done'));el.querySelector('#q-play').onclick=()=>play(QA[0].qA);el.querySelector('#q-slow').onclick=()=>play(QA[0].qSlow);el.querySelector('#q-again').onclick=()=>play(QA[0].qA);round()}}});

/* S6 · Station 2 · 问候/告别情境（看图说并匹配） */
addScreen('Station 2 · what do you say?',`<div style="text-align:center;width:1020px"><div class="row" style="justify-content:center;gap:16px"><span class="source-badge">STATION 2</span><h1 class="title sm">Look. Say it. Match it. <button class="speaker small" data-audio="a_t_what_do_you_say.mp3" style="vertical-align:middle"></button></h1></div><div class="row" style="margin-top:18px;align-items:flex-start"><div id="sit-scene"></div><div class="stack" id="sit-opts" style="width:430px"></div></div><div class="dots" id="sit-dots">${'<span class="dot"></span>'.repeat(3)}</div></div><div class="teacher"><b>情境三题：进教室 / 见朋友 / 放学离开。</b>先看图<b>口头说</b>该说什么，再点匹配句卡。人物移动方向是唯一提示（进门=Good morning，挥手离开=Good-bye）。3 题 2 对即过；方向提示只指一次。</div>`,el=>{let r=0;const dots=[...el.querySelectorAll('#sit-dots .dot')];const order=shuffle([0,1,2]);function round(){const s=SITS[order[r]];el.querySelector('#sit-scene').innerHTML=sceneHTML(s.id);el.querySelector('#sit-opts').innerHTML=shuffle(SIT_OPTS).map(t=>`<button class="phrase-opt" data-w="${t}">${t}</button>`).join('');el.querySelectorAll('#sit-opts [data-w]').forEach(b=>b.onclick=()=>{if(b.dataset.w===s.ans){b.classList.add('good');sfx('sfx_correct.mp3');play(s.ansA);dots[r]?.classList.add('done');r++;if(r<3)setTimeout(round,1300);else setTimeout(()=>{el.querySelector('#sit-opts').innerHTML='<p style="font-size:26px;font-weight:900;color:var(--green)">Station 2 clear!</p>';sfx('sfx_success.mp3')},1300)}else{b.classList.add('bad');sfx('sfx_wrong.mp3');setTimeout(()=>b.classList.remove('bad'),350)}})}return{onEnter(){r=0;dots.forEach(d=>d.classList.remove('done'));round()}}});

/* S7 · Station 3 · 颜色听辨气球（选项每题换位） */
addScreen('Station 3 · color balloons',`<div style="width:1060px"><div class="row" style="justify-content:space-between"><div class="row" style="width:auto;gap:16px"><span class="source-badge">STATION 3</span><h1 class="title sm">Pop the color you hear</h1></div><button class="mini-pill blue" id="cb-start">Start · 3 rounds</button></div><div id="cb-field" style="position:relative;height:400px;margin-top:10px"></div><div class="dots" id="cb-dots">${'<span class="dot"></span>'.repeat(3)}</div></div><div class="teacher"><b>听颜色词点气球，每题选项换位（防位置猜测）。</b>3 题 2 对即过。错误固定动作：只补混淆色——两色并排对比 + 慢音一次（点 Slow），不重教全部颜色。<div class="teacher-row"><button class="error" id="cb-slow">▶ Slow replay</button></div></div>`,el=>{const POS=[[80,40],[420,140],[760,30],[940,160]];let rounds=[],n=0,cur='';const dots=[...el.querySelectorAll('#cb-dots .dot')];function layout(){const opts=shuffle([cur,...shuffle(COLORS.filter(c=>c.en!==cur)).slice(0,3)]);el.querySelector('#cb-field').innerHTML=opts.map((c,i)=>balloonCol(c,POS[i][0],POS[i][1])).join('');el.querySelectorAll('.balloon').forEach(b=>b.onclick=()=>{if(!cur)return;if(b.dataset.w===cur){b.style.transform='scale(0)';sfx('sfx_correct.mp3');dots[n]?.classList.add('done');setTimeout(next,700)}else{b.style.animation='shake .35s';sfx('sfx_wrong.mp3');setTimeout(()=>b.style.animation='floaty 3.2s ease-in-out infinite',400)}})}function next(){n++;if(n>=3){cur='';toast('Station 3 clear');sfx('sfx_success.mp3');return}cur=rounds[n];layout();setTimeout(()=>play(`a_t_${cur}.mp3`),350)}el.querySelector('#cb-start').onclick=()=>{rounds=shuffle(COLORS).slice(0,3).map(c=>c.en);n=-1;dots.forEach(d=>d.classList.remove('done'));next()};el.querySelector('#cb-slow').onclick=()=>{if(cur)play(`a_t_${cur}_slow.mp3`)};return{onEnter(){const preview=shuffle(COLORS).slice(0,4);el.querySelector('#cb-field').innerHTML=preview.map((c,i)=>balloonCol(c,POS[i][0],POS[i][1])).join('');el.querySelectorAll('.balloon').forEach(b=>b.onclick=()=>play(`a_t_${b.dataset.w}.mp3`))}}});

/* S8 · Station 4 · A–H 听选 */
addScreen('Station 4 · hear the letter',`<div style="text-align:center;width:980px"><div class="row" style="justify-content:center;gap:16px"><span class="source-badge">STATION 4</span><h1 class="title sm">Hear it. Tap the letter.</h1></div><div class="card copy" style="margin-top:20px"><div class="row"><button class="speaker large" id="lk-play"></button><div class="row" id="lk-opts" style="width:auto"></div></div><div class="dots" id="lk-dots">${'<span class="dot"></span>'.repeat(3)}</div></div></div><div class="teacher"><b>A–H 听名选卡，选项每次洗牌。</b>3 题 2 对即过。错误固定动作：形近/音近对比对（${''}C–G、B–D 等）并排 + 慢音一次。<div class="teacher-row"><button class="error" id="lk-slow">▶ Slow replay</button></div></div>`,el=>{let rounds=[],n=0,cur='';const dots=[...el.querySelectorAll('#lk-dots .dot')];function round(){cur=rounds[n];const opts=shuffle([cur,...shuffle(KEY8.filter(L=>L!==cur)).slice(0,3)]);el.querySelector('#lk-opts').innerHTML=opts.map(ltrBtn).join('');setTimeout(()=>play(`a_t_ltr_${cur}.mp3`),300);el.querySelectorAll('#lk-opts [data-w]').forEach(b=>b.onclick=()=>{if(b.dataset.w===cur){b.classList.add('good');sfx('sfx_correct.mp3');dots[n]?.classList.add('done');n++;if(n<3)setTimeout(round,900);else setTimeout(()=>{el.querySelector('#lk-opts').innerHTML='<p style="font-size:26px;font-weight:900;color:var(--green)">Station 4 clear!</p>';sfx('sfx_success.mp3')},900)}else{b.classList.add('bad');sfx('sfx_wrong.mp3');setTimeout(()=>b.classList.remove('bad'),350)}})}el.querySelector('#lk-play').onclick=()=>{if(cur)play(`a_t_ltr_${cur}.mp3`)};el.querySelector('#lk-slow').onclick=()=>{if(cur)play(`a_t_ltr_${cur}_slow.mp3`)};return{onEnter(){rounds=shuffle(KEY8).slice(0,3);n=0;dots.forEach(d=>d.classList.remove('done'));round()}}});

/* S9 · A–H 短序列补缺 */
addScreen('Letters · fill the gap',`<div style="width:1000px;text-align:center"><h1 class="title sm">Which letter is missing?</h1><div class="card copy" style="margin-top:20px"><div class="seq-line" id="gap-line"></div><div class="row" id="gap-opts" style="margin-top:22px"></div></div><p class="subtitle">Say it first, then tap.</p></div><div class="teacher"><b>序列补缺两题（A B __ D 型）。</b>先口头补、再点卡；错给慢音，不批评。这是校内 Workbook 高频题型。</div>`,el=>{const rounds=[{seq:'AB_D',miss:'C'},{seq:'EF_H',miss:'G'}];let r=0;function render(){const q=rounds[r];el.querySelector('#gap-line').innerHTML=[...q.seq].map(ch=>ch==='_'?`<span style="display:inline-block;min-width:56px;border-bottom:7px dashed var(--coral);color:var(--coral)">?</span>`:`<span style="color:${TILE[ch]}">${ch}</span>`).join(' ');const opts=shuffle([q.miss,...shuffle(KEY8.filter(x=>x!==q.miss)).slice(0,2)]);el.querySelector('#gap-opts').innerHTML=opts.map(ltrBtn).join('');el.querySelectorAll('#gap-opts [data-w]').forEach(b=>b.onclick=()=>{if(b.dataset.w===q.miss){b.classList.add('good');play(`a_t_ltr_${q.miss}.mp3`);sfx('sfx_correct.mp3');r++;if(r<rounds.length)setTimeout(render,900);else setTimeout(()=>{el.querySelector('#gap-line').textContent='Well done!';el.querySelector('#gap-opts').innerHTML='';sfx('sfx_success.mp3')},900)}else{b.classList.add('bad');setTimeout(()=>b.classList.remove('bad'),350)}})}return{onEnter(){r=0;render()}}});

/* S10 · 字母描写动作（空中描写，书写转家庭） */
addScreen('Trace it in the air',`<div style="text-align:center"><h1 class="title sm">Trace it in the air <button class="speaker small" data-audio="a_t_trace_air.mp3" style="vertical-align:middle"></button></h1><div class="row" style="margin-top:16px;gap:60px"><div><div class="outline-ltr">B</div><p class="subtitle" style="text-align:center">big B</p></div><div><div class="outline-ltr" style="-webkit-text-stroke-color:var(--coral)">G</div><p class="subtitle" style="text-align:center">big G</p></div></div><div class="row" style="margin-top:10px"><button class="mini-pill" data-audio="a_t_ltr_B.mp3">▶ B</button><button class="mini-pill" data-audio="a_t_ltr_G.mp3">▶ G</button><button class="mini-pill" data-audio="a_t_trace.mp3">▶ Trace</button></div></div><div class="teacher"><b>描写只做"空中描 + 点线一遍"</b>：教师示范手指空描，学生跟描两次。详细书写（Workbook 描写行）<b>转家庭作业</b>，不在课堂耗时挤占语言练习。</div>`,null);

/* S11 · 四类示范题回顾 */
addScreen('Four task types · recap',`<div style="text-align:center;width:1080px"><h1 class="title sm">You know these four</h1><div class="station-map">${[['qa','Listen and answer','a_t_station_qa.mp3',"What's your name? → My name's ___."],['sit','What do you say?','a_t_station_sit.mp3','into class → Good morning.'],['col','Listen for the color','a_t_station_col.mp3','hear "green" → tap green'],['ltr','Listen for the letter','a_t_station_ltr.mp3','hear /dʒiː/ → tap G']].map(([k,t,au,eg],i)=>`<div class="station-card" style="border-top-color:${['#1670e8','#37b56a','#ff735e','#8e5bd6'][i]}"><div class="ic">${icSVG(ST_META[k].icon)}</div><strong>${t}</strong><p>${eg}</p><button class="mini-pill" data-audio="${au}" style="margin-top:10px;font-size:15px;padding:9px 16px">▶ Hear it</button></div>`).join('')}</div></div><div class="teacher"><b>示范题回顾（60 秒）</b>：四张卡逐一点播，学生用一句话说"这站要做什么"。说不出就看 S4 操作词图标，不展开重教。</div>`,null);

/* S12 · 60 秒 School Rush 混合题（主游戏） */
addScreen('School Rush · 60 seconds',`<div class="mission"><span class="source-badge">BEAT THE CLOCK</span><div class="timer-big" id="r-timer" style="margin-top:6px">60</div><div class="card copy" style="margin-top:8px;min-height:330px"><div id="r-prompt" class="row" style="gap:16px"></div><div class="row" id="r-opts" style="margin-top:18px;flex-wrap:wrap"></div></div><div class="row" style="margin-top:12px"><button class="mini-pill blue" id="r-start">Start rush</button><span class="subtitle" id="r-score" style="margin:0"></span></div></div><div class="teacher"><b>School Rush：四类混合 8 题，速度次于正确。</b>每题错后暂停：先分类错误（点下方），再继续。不靠位置猜测——选项每题换位。<div class="teacher-row"><span>Mark error:</span>${ERR_TYPES.slice(0,6).map(e=>`<button class="error" data-e="${e}">${e}</button>`).join('')}</div></div>`,el=>{const RUSH=[{t:'col',v:'red'},{t:'ltr',v:'C'},{t:'qa',v:0},{t:'sit',v:1},{t:'col',v:'green'},{t:'ltr',v:'F'},{t:'qa',v:1},{t:'sit',v:2}];let hits=0,ti=0,tleft=60,busy=false,lastTask='';function renderTask(){const t=RUSH[ti];const pr=el.querySelector('#r-prompt'),op=el.querySelector('#r-opts');if(t.t==='col'){pr.innerHTML=`<button class="speaker small" id="r-play"></button><b style="font-size:24px">Tap the color you hear</b>`;op.innerHTML=shuffle([t.v,...shuffle(COLORS.filter(c=>c.en!==t.v)).slice(0,3).map(c=>c.en)]).map(en=>swBtn(COLORS.find(c=>c.en===en))).join('')}else if(t.t==='ltr'){pr.innerHTML=`<button class="speaker small" id="r-play"></button><b style="font-size:24px">Tap the letter you hear</b>`;op.innerHTML=shuffle([t.v,...shuffle(KEY8.filter(L=>L!==t.v)).slice(0,3)]).map(ltrBtn).join('')}else if(t.t==='qa'){const item=QA[t.v];pr.innerHTML=`<button class="speaker small" id="r-play"></button><b style="font-size:24px">Say it, then tap the answer</b>`;op.innerHTML=shuffle([item.ans,QA[1-t.v].ans]).map(x=>`<button class="phrase-opt" data-w="${x}">${x}</button>`).join('')}else{const s=SITS[t.v];pr.innerHTML=`${sceneHTML(s.id)}`;pr.querySelector('.scene').style.width='300px';pr.querySelector('.scene').style.height='170px';pr.querySelectorAll('.sc-char').forEach(im=>im.style.height='120px');op.innerHTML=shuffle([s.ans,...SIT_OPTS.filter(x=>x!==s.ans).slice(0,1)]).map(x=>`<button class="phrase-opt" data-w="${x}">${x}</button>`).join('')}const playNow=()=>{if(t.t==='col')play(`a_t_${t.v}.mp3`);else if(t.t==='ltr')play(`a_t_ltr_${t.v}.mp3`);else if(t.t==='qa')play(QA[t.v].qA);else play('a_t_what_do_you_say.mp3')};const pb=pr.querySelector('#r-play');if(pb)pb.onclick=playNow;setTimeout(playNow,300);lastTask=t.t;op.querySelectorAll('[data-w]').forEach(b=>b.onclick=()=>{if(!busy)return;const right=(t.t==='col'&&b.dataset.w===t.v)||(t.t==='ltr'&&b.dataset.w===t.v)||(t.t==='qa'&&b.dataset.w===QA[t.v].ans)||(t.t==='sit'&&b.dataset.w===SITS[t.v].ans);if(right){hits++;b.classList.add('good');sfx('sfx_correct.mp3');ti++;if(ti<RUSH.length&&tleft>0)setTimeout(renderTask,600);else end()}else{b.classList.add('bad');sfx('sfx_wrong.mp3');setTimeout(()=>b.classList.remove('bad'),350)}})}function end(){busy=false;clearInterval(liveTimer);results.rushHits=hits;el.querySelector('#r-score').innerHTML=`<b>${hits}</b> / ${RUSH.length} tasks!`;el.querySelector('#r-opts').innerHTML='';el.querySelector('#r-prompt').innerHTML=`<b style="font-size:30px;color:var(--green)">Rush complete!</b>`;sfx('sfx_success.mp3')}el.querySelector('#r-start').onclick=()=>{hits=0;ti=0;tleft=60;busy=true;play('a_t_school_rush.mp3');el.querySelector('#r-score').textContent='';el.querySelector('#r-timer').textContent='60';renderTask();liveTimer=setInterval(()=>{tleft--;el.querySelector('#r-timer').textContent=tleft;if(tleft<=0)end()},1000)};el.querySelectorAll('.error').forEach(b=>b.onclick=()=>{results.errors?results.errors.push({item:lastTask,type:b.dataset.e,at:'rush'}):0;toast('Marked: '+b.dataset.e)});return{onEnter(){el.querySelector('#r-prompt').innerHTML=`<b style="font-size:26px">8 mixed tasks · colors · letters · questions · situations</b>`;el.querySelector('#r-opts').innerHTML=''}}});

/* ---------- Check/Exit 共用任务渲染器 ---------- */
function taskHTML(t){
 if(t.st==='qa'){const item=QA[t.idx];return{prompt:`<button class="speaker large" id="t-play"></button><b style="font-size:24px">Say YOUR answer, then tap it</b>`,choices:null,buildChoices:()=>shuffle([item.ans,QA[1-t.idx].ans]).map(x=>`<button class="phrase-opt" data-w="${x}">${x}</button>`).join(''),right:item.ans,play:()=>play(item.qA),help:'My … / I\'m …'}}
 if(t.st==='sit'){const s=SITS[t.idx];return{prompt:`${sceneHTML(s.id)}`,choices:shuffle([s.ans,...SIT_OPTS.filter(x=>x!==s.ans).slice(0,1)]).map(x=>`<button class="phrase-opt" data-w="${x}">${x}</button>`).join(''),right:s.ans,play:()=>play('a_t_what_do_you_say.mp3'),help:s.ans.split(' ')[0]+' …'}}
 if(t.st==='col'){const c=COLORS.find(x=>x.en===t.v);const opts=shuffle([t.v,...shuffle(COLORS.filter(x=>x.en!==t.v)).slice(0,2).map(x=>x.en)]);return{prompt:`<button class="speaker large" id="t-play"></button><b style="font-size:24px">Tap the color you hear</b>`,choices:opts.map(en=>swBtn(COLORS.find(x=>x.en===en))).join(''),right:t.v,play:()=>play(`a_t_${t.v}.mp3`),help:'listen slow'}}
 const opts=shuffle([t.v,...shuffle(KEY8.filter(L=>L!==t.v)).slice(0,2)]);return{prompt:`<button class="speaker large" id="t-play"></button><b style="font-size:24px">Tap the letter you hear</b>`,choices:opts.map(ltrBtn).join(''),right:t.v,play:()=>play(`a_t_ltr_${t.v}.mp3`),help:'listen slow'}
}

/* S13 · Check 1：四站各一题（随机顺序）+ A/B/C + 错误分类 */
addScreen('Check 1 · four stations',`<div style="text-align:center;width:1020px"><h1 class="title sm">Check 1 · on your own</h1><div class="card copy" style="margin-top:16px;min-height:360px"><div class="row" id="c1-prompt" style="gap:18px"></div><div class="row" id="c1-opts" style="margin-top:18px;flex-wrap:wrap"></div><div class="row" style="margin-top:14px"><button class="mini-pill blue" id="c1-show" style="display:none">Show choices</button></div><div class="dots" id="c1-dots">${'<span class="dot"></span>'.repeat(4)}</div></div></div><div class="teacher"><b>Check 1 独立检测（无支架、无阿语）</b>：四站各一题、顺序随机；学生先说后代点。每题作答后教师定级 A/B/C；B/C 必须点错误分类，再进下一题。<div class="teacher-row" id="c1-grade" style="display:none"><span id="c1-stname"><b>Grade:</b></span><button class="grade" data-g="A">A · Independent</button><button class="grade" data-g="B">B · With help</button><button class="grade" data-g="C">C · Not yet</button></div><div class="teacher-row" id="c1-err" style="display:none"><span>Error:</span>${ERR_TYPES.map(e=>`<button class="error" data-e="${e}">${e}</button>`).join('')}<button class="error" id="c1-next" style="background:var(--sky)">Continue ▶</button></div></div>`,el=>{const tasks=shuffle([{st:'qa',idx:1},{st:'sit',idx:2},{st:'col',v:'purple'},{st:'ltr',v:'G'}]);let i=0,answered=false;const dots=[...el.querySelectorAll('#c1-dots .dot')];function render(){answered=false;el.querySelector('#c1-grade').style.display='none';el.querySelector('#c1-err').style.display='none';const t=tasks[i],h=taskHTML(t);el.querySelector('#c1-prompt').innerHTML=h.prompt;const sc=el.querySelector('#c1-prompt .scene');if(sc){sc.style.width='330px';sc.style.height='180px';sc.querySelectorAll('.sc-char').forEach(im=>im.style.height='130px')}if(h.choices===null){el.querySelector('#c1-opts').innerHTML='';el.querySelector('#c1-show').style.display='';el.querySelector('#c1-show').onclick=()=>{el.querySelector('#c1-show').style.display='none';el.querySelector('#c1-opts').innerHTML=h.buildChoices();bindOpts(h)}}else{el.querySelector('#c1-show').style.display='none';el.querySelector('#c1-opts').innerHTML=h.choices;bindOpts(h)}const pb=el.querySelector('#t-play');if(pb)pb.onclick=h.play;setTimeout(h.play,400)}function bindOpts(h){el.querySelectorAll('#c1-opts [data-w]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;if(b.dataset.w===h.right){b.classList.add('good');sfx('sfx_correct.mp3')}else{b.classList.add('bad');sfx('sfx_wrong.mp3')}dots[i]?.classList.add('done');el.querySelector('#c1-stname').innerHTML=`<b>${ST_META[tasks[i].st].name}:</b>`;el.querySelector('#c1-grade').style.display='flex'})}el.querySelectorAll('#c1-grade .grade').forEach(b=>b.onclick=()=>{const st=tasks[i].st;results.stations[st]={grade:b.dataset.g,errs:[]};if(b.dataset.g==='A'){i++;i<4?setTimeout(render,400):finish()}else el.querySelector('#c1-err').style.display='flex'});el.querySelectorAll('#c1-err .error[data-e]').forEach(b=>b.onclick=()=>{const st=tasks[i].st;results.stations[st].errs.push(b.dataset.e);b.style.background='var(--sun)'});el.querySelector('#c1-next').onclick=()=>{i++;i<4?render():finish()};function finish(){el.querySelector('#c1-prompt').innerHTML='<b style="font-size:30px;color:var(--green)">Check 1 done</b>';el.querySelector('#c1-opts').innerHTML='';el.querySelector('#c1-show').style.display='none';el.querySelector('#c1-grade').style.display='none';el.querySelector('#c1-err').style.display='none';sfx('sfx_success.mp3')}return{onEnter(){noAr();i=0;dots.forEach(d=>d.classList.remove('done'));render()}}},{assessment:true});

/* S14 · 最低站定向补救（固定 7 步）+ 平行 Check 2 */
addScreen('Help one station · Check 2',`<div class="card copy" style="width:1000px;text-align:center"><div class="support" id="rs-support" style="box-shadow:none;border:2px dashed var(--line)"></div><div id="rs-stage" style="margin-top:14px;min-height:280px;display:grid;place-items:center"></div></div><div class="teacher"><b>只补最低站点 — 固定 7 步按顺序走，不全套重教。</b><div class="teacher-row" id="rs-pick"><span>Station:</span>${Object.keys(ST_META).map(k=>`<button class="error" data-st="${k}">${ST_META[k].name}</button>`).join('')}</div><div class="steps">${['Meaning','Slow','Contrast','Model','Build','Hide help','Try again'].map((x,i)=>`<button class="step" data-step="${i}">${i+1} · ${x}</button>`).join('')}</div><div id="rs-note" style="margin-top:10px">Start with Meaning.</div><div class="teacher-row" id="c2-row" style="display:none"><span><b>Check 2</b>（平行新题）:</span><button class="grade" data-g="A">A · Independent</button><button class="grade" data-g="B">B · With help</button><button class="grade" data-g="C">C · Not yet</button></div></div>`,el=>{let st='qa',idx=0;const support=el.querySelector('#rs-support'),stage=el.querySelector('#rs-stage'),note=el.querySelector('#rs-note');
 const PAR={qa:{t:{st:'qa',idx:0}},sit:{t:{st:'sit',idx:0}},col:{t:{st:'col',v:'blue'}},ltr:{t:{st:'ltr',v:'D'}}};
 function autoPick(){const failed=Object.keys(results.stations).find(k=>results.stations[k]&&results.stations[k].grade!=='A');return failed||'qa'}
 function reset(){idx=0;support.innerHTML=`<b style="font-size:26px">${ST_META[st].name}</b>`;stage.innerHTML=`<div style="transform:scale(1.8);opacity:.85">${icSVG(ST_META[st].icon)}</div>`;el.querySelectorAll('.step').forEach(b=>b.classList.remove('done'));el.querySelector('#c2-row').style.display='none';note.textContent='Start with Meaning.'}
 const ACT={
  qa:[()=>{support.innerHTML=`<div><b>${QA[0].q}</b><span class="ar" style="display:block;font-size:19px;color:var(--blue)">ما اسمك؟ — اسمع السؤال</span></div>`;stage.innerHTML=`<img src="${A}sec_char_noura.png" style="height:200px;border-radius:20px" alt="Noura">`},
   ()=>{play(QA[0].qSlow);support.innerHTML='Slow question — listen again.'},
   ()=>{support.innerHTML=`<div style="display:flex;gap:30px"><div><b>${QA[0].q}</b><br>→ ${QA[0].ans}</div><div><b>${QA[1].q}</b><br>→ ${QA[1].ans}</div></div>`;stage.innerHTML=''},
   ()=>{play(QA[0].qA);setTimeout(()=>play(QA[0].ansA),1600);support.innerHTML=`<b>${QA[0].q}</b> → <b>${QA[0].ans}</b>`},
   ()=>{support.innerHTML=`Say it with the frame:`;stage.innerHTML=`<span style="font-size:44px;font-weight:900">${QA[0].frame}</span>`},
   ()=>{support.innerHTML='';stage.innerHTML=`<b style="font-size:26px">No text. Listen and say.</b><button class="speaker large" id="rs-play" style="margin-top:12px"></button>`;stage.querySelector('#rs-play').onclick=()=>play(QA[0].qA)},
   ()=>tryAgain()],
  sit:[()=>{stage.innerHTML=sceneHTML('enter');support.innerHTML=`<div>Morning, into class.<span class="ar" style="display:block;font-size:19px;color:var(--blue)">في الصباح — تدخل الفصل</span></div>`},
   ()=>{play('a_t_good_morning_slow.mp3');support.innerHTML='Slow — listen again.'},
   ()=>{support.innerHTML=`<div style="display:flex;gap:30px"><div>INTO class → <b>Good morning.</b></div><div>OUT / leaving → <b>Good-bye.</b></div></div>`;stage.innerHTML=''},
   ()=>{play(SITS[0].ansA);support.innerHTML=`<b>${SITS[0].ans}</b>`},
   ()=>{support.innerHTML='Say it with the frame:';stage.innerHTML=`<span style="font-size:44px;font-weight:900">${SITS[0].frame}</span>`},
   ()=>{support.innerHTML='';stage.innerHTML=sceneHTML('enter')},
   ()=>tryAgain()],
  col:[()=>{const c=COLORS.find(x=>x.en==='blue');stage.innerHTML=`<button class="swatch-chip" style="background:${c.hex};width:160px;height:160px"></button>`;support.innerHTML=`<div><b>blue</b><span class="ar" style="display:block;font-size:19px;color:var(--blue)">أزرق</span></div>`},
   ()=>{play('a_t_blue_slow.mp3');support.innerHTML='Slow — listen again.'},
   ()=>{stage.innerHTML=`<div class="row">${swBtn(COLORS[2])}${swBtn(COLORS[0])}</div>`;support.innerHTML='<b>blue</b> ≠ <b>red</b>';stage.querySelectorAll('.swatch-chip').forEach(b=>b.onclick=()=>play(`a_t_${b.dataset.w}.mp3`))},
   ()=>{play('a_t_blue.mp3');support.innerHTML='<b>blue</b>'},
   ()=>{support.innerHTML='Say it with the frame:';stage.innerHTML=`<span style="font-size:44px;font-weight:900">It is ___.</span>`},
   ()=>{support.innerHTML='';stage.innerHTML=`<b style="font-size:26px">No labels. Just listen.</b>`},
   ()=>tryAgain()],
  ltr:[()=>{stage.innerHTML=`<span style="font-size:150px;font-weight:900;color:${TILE.D}">D</span>`;support.innerHTML=`<div><b>letter D</b><span class="ar" style="display:block;font-size:19px;color:var(--blue)">حرف دي</span></div>`},
   ()=>{play('a_t_ltr_D_slow.mp3');support.innerHTML='Slow — listen again.'},
   ()=>{stage.innerHTML=`<div class="row"><span style="font-size:110px;font-weight:900;color:${TILE.D}">D</span><span style="font-size:110px;font-weight:900;color:${TILE.B}">B</span></div>`;support.innerHTML='<b>D</b> ≠ <b>B</b>'},
   ()=>{play('a_t_ltr_D.mp3');support.innerHTML='<b>D</b> — say it.'},
   ()=>{support.innerHTML='Find D in the line:';stage.innerHTML=`<div class="seq-line">${KEY8.map(L=>`<span style="color:${TILE[L]};${L==='D'?'border-bottom:8px solid var(--coral)':''}">${L}</span>`).join(' ')}</div>`},
   ()=>{support.innerHTML='';stage.innerHTML=`<b style="font-size:26px">No help. Just listen.</b>`},
   ()=>tryAgain()]
 };
 function tryAgain(){note.innerHTML='<b>Check 2 — 平行新题，撤掉全部支架。</b>';const h=taskHTML(PAR[st].t);stage.innerHTML=`<div><div class="row" style="gap:16px">${h.prompt}</div><div class="row" id="rs-opts" style="margin-top:16px"></div></div>`;const sc=stage.querySelector('.scene');if(sc){sc.style.width='300px';sc.style.height='170px';sc.querySelectorAll('.sc-char').forEach(im=>im.style.height='120px')}const opts=h.choices===null?h.buildChoices():h.choices;stage.querySelector('#rs-opts').innerHTML=opts;const pb=stage.querySelector('#t-play');if(pb)pb.onclick=h.play;setTimeout(h.play,400);let done=false;stage.querySelectorAll('#rs-opts [data-w]').forEach(b=>b.onclick=()=>{if(done)return;done=true;if(b.dataset.w===h.right){b.classList.add('good');sfx('sfx_correct.mp3')}else{b.classList.add('bad');sfx('sfx_wrong.mp3')}el.querySelector('#c2-row').style.display='flex'})}
 el.querySelectorAll('#rs-pick [data-st]').forEach(b=>b.onclick=()=>{st=b.dataset.st;reset()});
 el.querySelectorAll('.step').forEach(b=>b.onclick=()=>{const i=+b.dataset.step;if(i!==idx)return;b.classList.add('done');idx++;note.textContent=['Meaning: 含义/短阿语提示','Slow: 慢速分段音频','Contrast: 混淆项对比','Model: 完整示范','Build: 句框支持','Hide help: 撤掉文字/阿语','Try again = Check 2'][i];ACT[st][i]()});
 el.querySelectorAll('#c2-row .grade').forEach(b=>b.onclick=()=>{results.check2[st]=b.dataset.g;results.stations[st]={grade:b.dataset.g,errs:results.stations[st]?.errs||[]};toast(`Check 2 · ${ST_META[st].name}: ${b.dataset.g}`)});
 return{onEnter(){st=autoPick();reset()}}});

/* S15 · 考试接口：Workbook 同源综合小测 */
addScreen('School test style',`<div style="text-align:center;width:1020px"><span class="source-badge">SCHOOL TEST STYLE · WORKBOOK pp.63–70</span><h1 class="title sm" style="margin-top:12px">Listen and circle. Listen and match.</h1><div class="card copy" style="margin-top:16px;min-height:330px"><div class="row" id="ex-prompt" style="gap:16px"></div><div class="row" id="ex-opts" style="margin-top:18px;flex-wrap:wrap"></div><div class="dots" id="ex-dots">${'<span class="dot"></span>'.repeat(4)}</div></div></div><div class="teacher"><b>考试接口（Workbook pp.63–70 题型仿题，真卷到位后替换）</b>：① Listen and circle ×2（字母+颜色）；② Listen and match ×2（问句→答句）。<b>先说后选</b>；全部为本单元已教内容。拿到家长真卷后按同结构替换题干。</div>`,el=>{const EX=[{kind:'circle',h:taskHTML({st:'ltr',v:'E'})},{kind:'circle',h:taskHTML({st:'col',v:'red'})},{kind:'match',h:taskHTML({st:'qa',idx:0})},{kind:'match',h:taskHTML({st:'qa',idx:1})}];let i=0;const dots=[...el.querySelectorAll('#ex-dots .dot')];function render(){const t=EX[i],h=t.h;play(t.kind==='circle'?'a_t_listen_circle.mp3':'a_t_listen_match.mp3');el.querySelector('#ex-prompt').innerHTML=`<span class="source-badge" style="background:var(--sky);box-shadow:none;color:var(--blue)">${t.kind==='circle'?'Listen and circle':'Listen and match'}</span>`+h.prompt;const pb=el.querySelector('#t-play');if(pb)pb.onclick=h.play;const opts=h.choices===null?h.buildChoices():h.choices;el.querySelector('#ex-opts').innerHTML=opts;setTimeout(h.play,1500);let done=false;el.querySelectorAll('#ex-opts [data-w]').forEach(b=>b.onclick=()=>{if(done)return;done=true;if(b.dataset.w===h.right){b.classList.add('good');sfx('sfx_correct.mp3')}else{b.classList.add('bad');sfx('sfx_wrong.mp3')}dots[i]?.classList.add('done');i++;if(i<4)setTimeout(render,900);else setTimeout(()=>{el.querySelector('#ex-prompt').innerHTML='<b style="font-size:28px;color:var(--green)">Test style: done!</b>';el.querySelector('#ex-opts').innerHTML='';sfx('sfx_success.mp3')},900)})}return{onEnter(){noAr();i=0;dots.forEach(d=>d.classList.remove('done'));render()}}},{assessment:true});

/* S16 · 四维 School Ready 能力卡 */
addScreen('School Ready report',`<div style="text-align:center"><span class="source-badge">SCHOOL READY</span><h1 class="title sm" style="margin-top:12px">My four powers</h1><div class="ability" style="margin:24px auto 0">${[['qa','I can listen and answer'],['sit','I can greet and say good-bye'],['col','I can hear the colors'],['ltr','I know A–H']].map(([k,t])=>`<div class="card"><div class="check">${icSVG(ST_META[k].icon)}</div><strong>${t}</strong><p class="result-line" id="ab-${k}"><span class="g-badge g-none">–</span></p></div>`).join('')}</div><p class="subtitle" id="ab-rush" style="margin-top:18px"></p></div><div class="teacher"><b>四维核对，不看总分</b>：逐项回填 S13/S14 定级（Check 2 覆盖 Check 1）；有 C 的维度就是复习页推送重点。截图发家长时四维徽章要清晰可见。</div>`,el=>{return{onEnter(){noAr();play('a_t_great_work.mp3');['qa','sit','col','ltr'].forEach(k=>{const g=results.check2[k]||results.stations[k]?.grade;el.querySelector('#ab-'+k).innerHTML=g?`<span class="g-badge g-${g}">${g}</span>`:'<span class="g-badge g-none">–</span>'});el.querySelector('#ab-rush').textContent=results.rushHits?`School Rush: ${results.rushHits} tasks in 60 seconds`:''}}},{assessment:true});

/* S17 · Exit：四站新题 + 个性化复习 QR */
addScreen('Exit task · four fresh ones',`<div class="layout" style="grid-template-columns:1.15fr 1fr"><div><h1 class="title sm">Four new tasks.<br>Say it. Tap it.</h1><div class="card copy" style="margin-top:16px;min-height:270px"><div class="row" id="x-prompt" style="gap:14px"></div><div class="row" id="x-opts" style="margin-top:14px;flex-wrap:wrap"></div><div class="dots" id="x-dots">${'<span class="dot"></span>'.repeat(4)}</div><div class="row" style="margin-top:10px"><button class="mini-pill" id="x-help">Help</button></div><div class="support" id="x-support" style="min-height:56px;font-size:22px;margin-top:10px"></div></div></div><div class="card copy"><h2 style="font-size:34px">At home</h2><p class="subtitle"><b>Workbook pp.63–70</b>：finish the listen-circle and match rows.</p><p class="ar subtitle">أكمل تمارين الاستماع والتوصيل في كتاب التمارين صفحة 63–70</p><div style="display:flex;align-items:center;gap:18px;margin-top:16px"><img src="${A}sec_qr_review.png" alt="home review QR" style="width:112px;height:112px;border-radius:14px"><a class="mini-pill blue" href="review/" style="display:inline-block;text-decoration:none">Open home review</a></div><div class="card" style="margin-top:16px;padding:16px;border-radius:18px;box-shadow:none;background:var(--sky)"><b>Say it</b><p class="subtitle" style="font-size:18px">Good-bye! See you again! <button class="speaker small" data-audio="a_t_goodbye_seeyou.mp3" style="vertical-align:middle"></button></p></div></div></div><div class="teacher"><b>Exit = 四站新题各一，先说后代点；Help 只给首词或慢音最小提示。</b>四题独立完成 ≥3 → 达标。<div class="teacher-row"><button class="error" id="x-pass">≥3 independent → 达标</button><button class="error" id="x-helpB">Needed help → B</button><button class="error" id="x-c">Not yet → C</button></div></div>`,el=>{const tasks=[{st:'qa',idx:0},{st:'sit',idx:1},{st:'col',v:'yellow'},{st:'ltr',v:'H'}];let i=0,curH=null;const dots=[...el.querySelectorAll('#x-dots .dot')];function render(){el.querySelector('#x-support').textContent='';const h=taskHTML(tasks[i]);curH=h;el.querySelector('#x-prompt').innerHTML=h.prompt;const sc=el.querySelector('#x-prompt .scene');if(sc){sc.style.width='290px';sc.style.height='160px';sc.querySelectorAll('.sc-char').forEach(im=>im.style.height='115px')}el.querySelector('#x-opts').innerHTML=h.choices===null?h.buildChoices():h.choices;const pb=el.querySelector('#t-play');if(pb)pb.onclick=h.play;setTimeout(h.play,400);let done=false;el.querySelectorAll('#x-opts [data-w]').forEach(b=>b.onclick=()=>{if(done)return;done=true;if(b.dataset.w===h.right){b.classList.add('good');sfx('sfx_correct.mp3')}else{b.classList.add('bad');sfx('sfx_wrong.mp3')}dots[i]?.classList.add('done');i++;if(i<4)setTimeout(render,900);else setTimeout(()=>{el.querySelector('#x-prompt').innerHTML='<b style="font-size:28px;color:var(--green)">School Ready!</b>';el.querySelector('#x-opts').innerHTML='';el.querySelector('#x-help').style.display='none';sfx('sfx_success.mp3')},900)})}el.querySelector('#x-help').onclick=()=>{if(!curH)return;if(curH.help==='listen slow'){const t=tasks[Math.min(i,3)];play(t.st==='col'?`a_t_${t.v}_slow.mp3`:`a_t_ltr_${t.v}_slow.mp3`)}else el.querySelector('#x-support').textContent=curH.help};el.querySelector('#x-pass').onclick=()=>toast('Exit: A · 达标');el.querySelector('#x-helpB').onclick=()=>toast('Exit: B');el.querySelector('#x-c').onclick=()=>toast('Exit: C');return{onEnter(){noAr();i=0;dots.forEach(d=>d.classList.remove('done'));el.querySelector('#x-help').style.display='';render()}}},{assessment:true});

screens.forEach((s,i)=>{const b=document.createElement('button');b.textContent=`${i+1} · ${s.title}`;b.onclick=()=>{$('#thumbs').classList.remove('open');show(i)};$('#thumbs').appendChild(b)});
const q=new URLSearchParams(location.search),start=Math.max(0,Math.min(16,(Number(q.get('p')||q.get('page'))||1)-1));if(q.get('teacher')==='1'){document.body.classList.add('teacher-on');$('#btn-teacher').setAttribute('aria-pressed','true')}if(q.get('ar')==='1'&&start<12){document.body.classList.add('ar-on');$('#btn-ar').setAttribute('aria-pressed','true')}fit();show(start);
